}

{
  "action": "VERIFY",
  "checkpoint": "PLAN-B",
  "rationale": "The environment explicitly instructs to 'verify every original and updated constraint' before proceeding to completion. This is a direct mapping to the VERIFY action, which ensures the plan's integrity against all known constraints (including the resource substitution from PLAN-B) prior to finalizing.",
